// ADR-006 §9 — loads the provisional (procedural) asset set generated by `pnpm assets:gen` and turns it into
// the two seams the renderer exposes: `TerrainTextures` (ground0..3 + noise) and `UnitAtlas`.
// Owner: art-pipeline + render-engineer (A3). Images are decoded with `createImageBitmap` so the alpha handling is
// explicit: terrain/noise are uploaded straight (no premultiply; the noise packs 4 independent channels), the
// unit atlas is premultiplied (what Pixi's blending expects). Everything is same-origin (COEP require-corp).
import { ImageSource, Rectangle, Texture } from 'pixi.js';
import {
  prepareGroundTexture,
  prepareNoiseTexture,
  type TerrainTextures,
} from '../render/terrain/textures';
import type { UnitAtlas } from '../render/entities/atlas';
import {
  parseAssetManifest,
  parseSheet,
  requiredUnitFrames,
  resolveAppearance,
  unitFrameName,
  usedAppearances,
  type AssetManifest,
} from './manifest';

export interface LoadedAssets {
  readonly manifest: AssetManifest;
  readonly terrain: TerrainTextures;
  readonly unitAtlas: UnitAtlas;
  /** Mean colour (0xRRGGBB) of ground0..3: the minimap's terrain colours. */
  readonly layerRgb: readonly [number, number, number, number];
  destroy(): void;
}

export interface LoadAssetsOptions {
  /** Directory URL of the generated set (default: `<BASE_URL>assets/provisional/`). */
  baseUrl?: string;
  /** `sprite` id (units.json) per typeId, in typeId order. */
  unitSprites: readonly string[];
  fetchFn?: typeof fetch;
}

const NO_PREMULTIPLY = { premultiplyAlpha: 'none', colorSpaceConversion: 'none' } as const;

function defaultBaseUrl(): string {
  const base = (import.meta as { env?: { BASE_URL?: string } }).env?.BASE_URL ?? '/';
  return `${base}assets/provisional/`;
}

async function fetchOk(f: typeof fetch, url: string): Promise<Response> {
  const res = await f(url);
  if (!res.ok) throw new Error(`asset ${url}: HTTP ${res.status}`);
  return res;
}

async function loadBitmap(
  f: typeof fetch,
  url: string,
  mode: 'straight' | 'premultiplied',
): Promise<ImageBitmap> {
  const blob = await (await fetchOk(f, url)).blob();
  return createImageBitmap(
    blob,
    mode === 'straight' ? NO_PREMULTIPLY : { premultiplyAlpha: 'premultiply' },
  );
}

/** Mean RGB of a bitmap (downscaled by the browser to 16×16 first: cheap and good enough for a minimap). */
function meanRgb(bmp: ImageBitmap): number {
  const n = 16;
  const cv = document.createElement('canvas');
  cv.width = cv.height = n;
  const ctx = cv.getContext('2d', { willReadFrequently: true });
  if (ctx === null) return 0x606060;
  ctx.drawImage(bmp, 0, 0, n, n);
  const d = ctx.getImageData(0, 0, n, n).data;
  let r = 0;
  let g = 0;
  let b = 0;
  for (let i = 0; i < d.length; i += 4) {
    r += d[i] ?? 0;
    g += d[i + 1] ?? 0;
    b += d[i + 2] ?? 0;
  }
  const px = n * n;
  return (Math.round(r / px) << 16) | (Math.round(g / px) << 8) | Math.round(b / px);
}

function imageSource(bmp: ImageBitmap, alphaMode: 'no-premultiply-alpha' | 'premultiplied-alpha') {
  return new ImageSource({ resource: bmp, alphaMode });
}

export async function loadProvisionalAssets(opts: LoadAssetsOptions): Promise<LoadedAssets> {
  const f = opts.fetchFn ?? fetch.bind(globalThis);
  const base = opts.baseUrl ?? defaultBaseUrl();
  const url = (name: string): string => base + name;

  const manifest = parseAssetManifest(await (await fetchOk(f, url('manifest.json'))).json());
  const sheet = parseSheet(await (await fetchOk(f, url(manifest.atlases.units.data))).json());
  const appearances = usedAppearances(manifest, opts.unitSprites);
  const missing = requiredUnitFrames(manifest, appearances).filter((n) => !(n in sheet.frames));
  if (missing.length > 0)
    throw new Error(`units atlas is missing ${missing.length} frames (first: ${missing[0]})`);

  const [grounds, noiseBmp, atlasBmp] = await Promise.all([
    Promise.all(manifest.textures.ground.map((n) => loadBitmap(f, url(n), 'straight'))),
    loadBitmap(f, url(manifest.textures.noise), 'straight'),
    loadBitmap(f, url(manifest.atlases.units.image), 'premultiplied'),
  ]);
  const layerRgb = grounds.map(meanRgb) as unknown as LoadedAssets['layerRgb'];

  const owned: Array<{ destroy(d?: boolean): void }> = [];
  const groundTex = grounds.map((b) => {
    const t = prepareGroundTexture(new Texture({ source: imageSource(b, 'no-premultiply-alpha') }));
    owned.push(t);
    return t;
  }) as unknown as TerrainTextures['ground'];
  const noiseTex = prepareNoiseTexture(
    new Texture({ source: imageSource(noiseBmp, 'no-premultiply-alpha') }),
  );
  owned.push(noiseTex);
  const terrain: TerrainTextures = { ground: groundTex, noise: noiseTex };

  // Unit atlas: one Texture per frame of every used appearance (a few hundred small views of one source).
  const atlasSource = imageSource(atlasBmp, 'premultiplied-alpha');
  atlasSource.scaleMode = 'linear';
  const dirs = manifest.dirs;
  const anims = manifest.anim.idle + manifest.anim.walk;
  const frames = new Map<string, Texture>();
  for (const a of appearances)
    for (const layer of ['body', 'team'] as const)
      for (let d = 0; d < dirs; d++)
        for (let k = 0; k < anims; k++) {
          const name = unitFrameName(a, layer, d, k);
          const fr = sheet.frames[name]!.frame;
          frames.set(
            name,
            new Texture({ source: atlasSource, frame: new Rectangle(fr.x, fr.y, fr.w, fr.h) }),
          );
        }
  const appearanceOfType = opts.unitSprites.map((s) => resolveAppearance(manifest, s));
  const frameOf = (typeId: number, layer: 'body' | 'team', dir: number, anim: number): Texture =>
    frames.get(unitFrameName(appearanceOfType[typeId] ?? 'generic', layer, dir, anim)) ??
    (frames.get(unitFrameName('generic', layer, dir, anim)) as Texture);
  const unitAtlas: UnitAtlas = {
    dirs,
    body: (t, d, a) => frameOf(t, 'body', d, a),
    team: (t, d, a) => frameOf(t, 'team', d, a),
    bodyTint: () => 0xffffff,
    destroy: () => {
      for (const t of frames.values()) t.destroy();
      atlasSource.destroy();
      atlasBmp.close();
    },
  };

  return {
    manifest,
    terrain,
    unitAtlas,
    layerRgb,
    destroy() {
      unitAtlas.destroy();
      for (const t of owned) t.destroy(true);
      for (const b of [...grounds, noiseBmp]) b.close();
    },
  };
}
